void FlammableUpdate::stopBurningSound()
{
	if (m_audioHandle)
	{
		reinterpret_cast<AudioManagerSlots *>(TheAudio)->removeAudioEvent( m_audioHandle );
		m_audioHandle = 0;
	}
}

//-------------------------------------------------------------------------------------------------
//-------------------------------------------------------------------------------------------------
Bool FlammableUpdate::wouldIgnite()
{
	if( m_status == FS_NORMAL )
		return TRUE;

	return FALSE;
}

